'use client';
import {useEffect,useRef,useState,useId,cloneElement} from 'react';
import {ArrowUpRight,ArrowDownLeft,ArrowRight,Building2,Check,CheckCheck,ChevronDown,CircleHelp,Clock3,LayoutDashboard,LogOut,MessageCircle,Plus,RefreshCw,Search,Send,Settings2,ShieldCheck,Sparkles,Users,Wallet,X,Link2,LockKeyhole,Activity,Menu,AlertCircle,CheckCircle2,Unplug,SlidersHorizontal,Eye} from 'lucide-react';
import {browserClient} from '../lib/supabase';
import {createDemo} from '../lib/demo';
const NAV=[['overview','Resumen',LayoutDashboard],['messages','Mensajes',MessageCircle],['whatsapp','WhatsApp',Link2],['social','Instagram y Facebook',MessageCircle],['team','Equipo',Users],['plan','Mi plan',Wallet]];
const LABELS={overview:'Resumen',messages:'Mensajes',whatsapp:'WhatsApp',social:'Instagram y Facebook',team:'Equipo',plan:'Mi plan',businesses:'Mis negocios',settings:'Configuración',admin:'Administración',plans:'Gestionar planes'};
const ROLES={owner:'Propietario',admin:'Administrador',agent:'Agente',viewer:'Lector'};
const STATUS={received:'Recibido',sending:'En proceso',accepted:'Aceptado por Meta',sent:'Enviado',delivered:'Entregado',read:'Leído',failed:'Fallido',unknown:'Sin confirmar'};
const fmt=n=>new Intl.NumberFormat('es-MX').format(n||0);
const date=v=>new Intl.DateTimeFormat('es-MX',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'}).format(new Date(v));
const blank={messages:[],members:[],activity:[],connection:null,metaChannels:[],usage:0,inbound:0,role:null};
const DEMO_EMAIL='demo@nexo.local', DEMO_PASSWORD='NexoDemo2026!';
const CLIENT_DEMO_EMAIL='cliente@nexo.local', CLIENT_DEMO_PASSWORD='ClienteDemo2026!';
function Badge({children,tone='neutral'}){return <span className={`badge ${tone}`}>{children}</span>;}
function Field({label,children,hint}){const id=useId();return <div className="field"><label htmlFor={id}>{label}</label>{cloneElement(children,{id,"aria-describedby":hint?id+"-hint":undefined})}{hint&&<small id={id+"-hint"}>{hint}</small>}</div>;}
function Empty({icon:Icon=MessageCircle,title,children,action}){return <div className="empty"><span className="empty-icon"><Icon size={25}/></span><h3>{title}</h3><p>{children}</p>{action}</div>;}
function Modal({title,children,onClose}){const ref=useRef(),heading=useId();useEffect(()=>{const el=ref.current;el.showModal();return()=>el.close();},[]);return <dialog ref={ref} aria-labelledby={heading} onCancel={e=>{e.preventDefault();onClose();}} onClick={e=>{if(e.target===ref.current)onClose();}}><div className="modal-head"><h2 id={heading}>{title}</h2><button className="icon-button" aria-label="Cerrar" onClick={onClose}><X size={20}/></button></div>{children}</dialog>;}
function Form({children,onSubmit,busy,disabled=false,label='Guardar cambios'}){return <form onSubmit={e=>{e.preventDefault();onSubmit(Object.fromEntries(new FormData(e.currentTarget)));}}><fieldset disabled={busy||disabled}>{children}<div className="form-actions"><button className="button primary" type="submit">{busy?'Guardando…':label}<ArrowRight size={16}/></button></div></fieldset></form>;}
function MessageTable({messages,compact=false,onSelect}){if(!messages.length)return <Empty title="Aquí comienza la conversación">Los mensajes enviados y recibidos aparecerán en este espacio.</Empty>;return <div className="table-scroll"><table><thead><tr><th>Contacto / mensaje</th><th>Dirección</th><th>Estado</th><th>Fecha</th></tr></thead><tbody>{messages.slice(0,compact?5:200).map(m=><tr key={m.id}><td><div className="contact"><span className={`contact-icon ${m.direction}`}><MessageCircle size={17}/></span><div><button className="message-link" onClick={()=>onSelect(m)} aria-label={`Ver mensaje de ${m.phone}`}>+{m.phone}</button><span className="truncate">{m.kind==='template'?'Plantilla: '+m.content:m.content}</span>{m.error_code&&<small className="error-text">Código: {m.error_code}</small>}</div></div></td><td><span className="direction">{m.direction==='inbound'?<ArrowDownLeft size={14}/>:<ArrowUpRight size={14}/>} {m.direction==='inbound'?'Entrante':'Saliente'}</span></td><td><Badge tone={m.status==='failed'?'danger':m.status==='unknown'||m.status==='sending'?'warning':m.status==='read'?'purple':m.status==='received'?'neutral':'success'}>{m.status==='read'&&<CheckCheck size={13}/>} {STATUS[m.status]}</Badge></td><td className="nowrap muted">{date(m.created_at)}</td></tr>)}</tbody></table></div>;}
export default function Dashboard(){
 const [ready,setReady]=useState(false),[demo,setDemo]=useState(false),[demoRole,setDemoRole]=useState('admin'),[demoData,setDemoData]=useState(createDemo),[session,setSession]=useState(null),[authMode,setAuthMode]=useState('login'),[authNotice,setAuthNotice]=useState('');
 const [workspaces,setWorkspaces]=useState([]),[plans,setPlans]=useState([]),[wid,setWid]=useState(''),[details,setDetails]=useState(blank),[isAdmin,setIsAdmin]=useState(false),[loaded,setLoaded]=useState('');
 const [section,setSection]=useState('overview'),[loading,setLoading]=useState(false),[busy,setBusy]=useState(false),[error,setError]=useState(''),[notice,setNotice]=useState(''),[modal,setModal]=useState(null),[reload,setReload]=useState(0),[mobile,setMobile]=useState(false),[search,setSearch]=useState(''),[filter,setFilter]=useState('all'),[requestId,setRequestId]=useState(''),[messageKind,setMessageKind]=useState('text');
 const sb=browserClient();
 useEffect(()=>{const params=new URLSearchParams(location.search);setDemo(params.get('demo')==='1');setDemoRole(params.get('role')==='client'?'client':'admin');setDemoRole(params.get('role')==='client'?'client':'admin');if(params.get('recovery')==='1')setAuthMode('update');if(!sb){setReady(true);return;}let alive=true;sb.auth.getSession().then(({data,error})=>{if(alive){if(error)setError('No se pudo recuperar la sesión.');setSession(data.session);setReady(true);}});const {data:{subscription}}=sb.auth.onAuthStateChange((event,current)=>{setSession(current);if(event==='PASSWORD_RECOVERY')setAuthMode('update');});return()=>{alive=false;subscription.unsubscribe();};},[sb]);
 useEffect(()=>{if(demo){const visible=demoRole==='client'?demoData.workspaces.filter(w=>w.id==='demo-1'):demoData.workspaces;setWorkspaces(visible);setPlans(demoData.plans);setIsAdmin(demoRole==='admin');if(!visible.some(w=>w.id===wid))setWid(visible[0]?.id||'');return;}if(!session){setWorkspaces([]);setWid('');setIsAdmin(false);return;}let alive=true;setLoading(true);Promise.all([sb.from('workspaces').select('*').order('created_at'),sb.from('plans').select('*').order('monthly_messages'),sb.rpc('is_platform_admin')]).then(r=>{if(!alive)return;const bad=r.find(x=>x.error);if(bad)throw bad.error;setWorkspaces(r[0].data);setPlans(r[1].data);setIsAdmin(r[2].data);setWid(old=>r[0].data.some(w=>w.id===old)?old:r[0].data[0]?.id||'');}).catch(e=>{if(alive)setError(e.message);}).finally(()=>{if(alive)setLoading(false);});return()=>{alive=false;};},[session?.user.id,demo,demoRole,demoData,reload]);
 useEffect(()=>{if(!wid){setDetails(blank);setLoaded('');return;}if(demo){const source=demoData.details[wid]||blank;setDetails(demoRole==='client'?{...source,role:'agent',members:source.members.filter(m=>m.role!=='owner')}:{...source});setLoaded(wid);return;}if(!session)return;let alive=true;setLoaded('');setDetails(blank);const now=new Date(),month=new Date(Date.UTC(now.getUTCFullYear(),now.getUTCMonth(),1)).toISOString();Promise.all([sb.from('memberships').select('*').eq('workspace_id',wid).order('created_at'),sb.from('messages').select('*').eq('workspace_id',wid).order('created_at',{ascending:false}).limit(200),sb.from('whatsapp_connections').select('*').eq('workspace_id',wid).maybeSingle(),sb.from('activity').select('*').eq('workspace_id',wid).order('created_at',{ascending:false}).limit(20),sb.rpc('workspace_usage',{wid}),sb.rpc('workspace_role',{wid}),sb.from('messages').select('id',{count:'exact',head:true}).eq('workspace_id',wid).eq('direction','inbound').gte('created_at',month),sb.from('meta_channels').select('*').eq('workspace_id',wid)]).then(r=>{if(!alive)return;const bad=r.find(x=>x.error);if(bad)throw bad.error;setDetails({members:r[0].data,messages:r[1].data,connection:r[2].data,activity:r[3].data,usage:Number(r[4].data),role:r[5].data,inbound:r[6].count,metaChannels:r[7].data||[]});setLoaded(wid);}).catch(e=>{if(alive)setError(e.message);});return()=>{alive=false;};},[wid,demo,demoRole,demoData,session?.user.id,reload]);
 useEffect(()=>{if(!notice)return;const timer=setTimeout(()=>setNotice(''),6500);return()=>clearTimeout(timer);},[notice]);
 const workspace=workspaces.find(w=>w.id===wid),plan=plans.find(p=>p.id===workspace?.plan_id),managing=['owner','admin'].includes(details.role),sending=['owner','admin','agent'].includes(details.role),dataReady=!wid||loaded===wid;
 function navigate(id){setSection(id);setMobile(false);setSearch('');setFilter('all');setError('');}
 function startDemo(role='admin'){history.replaceState(null,'',`/?demo=1${role==='client'?'&role=client':''}`);setDemoRole(role);setDemo(true);setAuthMode('login');setError('');setWid('');}
 async function logout(){if(demo){setDemo(false);setDemoRole('admin');setWid('');history.replaceState(null,'','/');}else await sb.auth.signOut();setSection('overview');setDetails(blank);}
 async function run(action,success){if(busy)return;setBusy(true);setError('');try{await action();setModal(null);if(success)setNotice(success);setReload(x=>x+1);}catch(e){setError(e.message||'No se pudo completar la operación.');}finally{setBusy(false);}}
 async function call(name,args){const{data,error}=await sb.rpc(name,args);if(error)throw error;return data;}
 async function api(body){const{data}=await sb.auth.getSession();const response=await fetch('/api/whatsapp',{method:'POST',headers:{'Content-Type':'application/json',Authorization:`Bearer ${data.session?.access_token||''}`},body:JSON.stringify(body)});let result;try{result=await response.json();}catch{throw new Error('No se pudo confirmar la operación. Actualiza la actividad antes de reintentar.');}if(!response.ok)throw new Error(result.error);return result;}
 function changeDemo(patch){setDemoData(d=>({...d,details:{...d.details,[wid]:{...d.details[wid],...patch}}}));}
 function openSend(){setRequestId(crypto.randomUUID());setMessageKind('text');setModal({type:'send'});}
 async function auth(v){setBusy(true);setError('');setAuthNotice('');try{if(authMode==='login'&&((v.email.toLowerCase()===DEMO_EMAIL&&v.password===DEMO_PASSWORD)||(v.email.toLowerCase()===CLIENT_DEMO_EMAIL&&v.password===CLIENT_DEMO_PASSWORD))){startDemo(v.email.toLowerCase()===CLIENT_DEMO_EMAIL?'client':'admin');setNotice('Sesión de demostración iniciada.');return;}if(!sb)throw new Error('Falta conectar Supabase. Puedes usar el acceso demo.');let r;if(authMode==='login')r=await sb.auth.signInWithPassword({email:v.email,password:v.password});if(authMode==='register')r=await sb.auth.signUp({email:v.email,password:v.password,options:{emailRedirectTo:location.origin}});if(authMode==='recover')r=await sb.auth.resetPasswordForEmail(v.email,{redirectTo:location.origin+'/?recovery=1'});if(authMode==='update')r=await sb.auth.updateUser({password:v.password});if(r.error)throw r.error;if(authMode==='register'&&!r.data.session)setAuthNotice('Revisa tu correo para confirmar tu cuenta y después inicia sesión.');if(authMode==='recover')setAuthNotice('Si existe una cuenta con ese correo, recibirás un enlace para restablecer tu contraseña.');if(authMode==='update'){setAuthMode('login');history.replaceState(null,'','/');setNotice('Contraseña actualizada.');}}catch(e){setError(e.message==='Invalid login credentials'?'Correo o contraseña incorrectos.':e.message);}finally{setBusy(false);}}
 if(!ready)return <div className="boot"><span className="brand-icon">n</span><p>Preparando tu espacio…</p></div>;
 if((!session&&!demo)||authMode==='update')return <div className="auth-shell"><aside className="auth-story"><a className="brand" href="/"><span className="brand-icon">n</span>nexo<span className="brand-dot">.</span></a><div><Badge tone="purple">TU NEGOCIO, CONECTADO</Badge><h1>Más cerca de tus clientes.<br/><em>Todo en un lugar.</em></h1><p>Tu equipo, tus negocios y cada conversación de WhatsApp. Un espacio para trabajar mejor.</p><div className="auth-features"><span><Building2/>Varios negocios, un solo acceso</span><span><MessageCircle/>Conversaciones que conectan</span><span><ShieldCheck/>Cada equipo, con sus permisos</span></div></div><small>Una plataforma pensada para tu operación diaria.</small></aside><main className="auth-main"><div className="auth-card"><span className="eyebrow">BIENVENIDO A NEXO</span><h2>{authMode==='register'?'Crea tu cuenta':authMode==='recover'?'Recupera tu acceso':authMode==='update'?'Elige una nueva contraseña':'Tu próximo paso empieza aquí'}</h2><p className="muted">{authMode==='login'?'Inicia sesión para entrar a tu espacio de trabajo.':authMode==='register'?'Regístrate y crea el espacio de tu negocio.':authMode==='recover'?'Te enviaremos un enlace a tu correo.':'Usa una contraseña de al menos 12 caracteres.'}</p>{authMode==='login'&&<div className="setup-note"><Eye size={19}/><span>Admin: <strong>{DEMO_EMAIL}</strong> · <strong>{DEMO_PASSWORD}</strong><br/>Cliente: <strong>{CLIENT_DEMO_EMAIL}</strong> · <strong>{CLIENT_DEMO_PASSWORD}</strong></span></div>}{error&&<div className="inline-error" role="alert">{error}</div>}{authNotice&&<div className="inline-success" role="status">{authNotice}</div>}<Form onSubmit={auth} busy={busy} disabled={authMode!=='login'&&!sb} label={authMode==='register'?'Crear cuenta':authMode==='recover'?'Enviar enlace':authMode==='update'?'Actualizar contraseña':'Iniciar sesión'}>{authMode!=='update'&&<Field label="Correo electrónico"><input name="email" type="email" autoComplete="email" placeholder="tu@negocio.com" required maxLength={254}/></Field>}{authMode!=='recover'&&<Field label="Contraseña"><input name="password" type="password" autoComplete={authMode==='login'?'current-password':'new-password'} required minLength={authMode==='login'?1:12} maxLength={128}/></Field>}</Form>{authMode==='login'&&<button className="text-button auth-link" onClick={()=>{setAuthMode('recover');setError('');}}>Olvidé mi contraseña</button>}<p className="auth-switch">{authMode==='login'?'¿Aún no tienes una cuenta? ':'¿Ya tienes una cuenta? '}<button className="text-button" onClick={()=>{setAuthMode(authMode==='login'?'register':'login');setError('');setAuthNotice('');}}>{authMode==='login'?'Regístrate':'Inicia sesión'}</button></p><div className="auth-divider"><span>o conoce la plataforma</span></div><button className="button demo-button" onClick={startDemo}><Eye size={18}/>Explorar demo interactiva<ArrowRight size={17}/></button><small className="demo-disclaimer">Datos de ejemplo. Sin registro y sin envíos reales.</small></div></main></div>;
 return <div className="app-shell">{mobile&&<button className="sidebar-backdrop" aria-label="Cerrar menú" onClick={()=>setMobile(false)}/>}<aside className={`sidebar ${mobile?'open':''}`}><a className="brand" href={demo?'/?demo=1':'/'}><span className="brand-icon">n</span>nexo<span className="brand-dot">.</span></a><div className="workspace-label">ESPACIO DE TRABAJO</div><div className="workspace-switch"><span className="workspace-avatar">{workspace?.name?.slice(0,1)||'N'}</span><div><strong>{workspace?.name||'Tu espacio'}</strong><small>{plan?.name||'Comienza aquí'}</small></div><ChevronDown size={15}/><select aria-label="Cambiar negocio" value={wid} onChange={e=>{setWid(e.target.value);setError('');setModal(null);}}>{!wid&&<option value="">Selecciona un negocio</option>}{workspaces.map(w=><option key={w.id} value={w.id}>{w.name}</option>)}</select></div><div className="nav-label">PRINCIPAL</div><nav aria-label="Navegación principal">{NAV.map(([id,label,Icon])=><button className={section===id?'active':''} key={id} onClick={()=>navigate(id)}><Icon size={19}/>{label}{id==='whatsapp'&&details.connection&&<span className="nav-status"/>}</button>)}<div className="nav-label">ORGANIZACIÓN</div><button className={section==='businesses'?'active':''} onClick={()=>navigate('businesses')}><Building2 size={19}/>Mis negocios</button><button className={section==='settings'?'active':''} onClick={()=>navigate('settings')}><Settings2 size={19}/>Configuración</button>{isAdmin&&<><div className="nav-label">PLATAFORMA</div><button className={section==='admin'?'active':''} onClick={()=>navigate('admin')}><ShieldCheck size={19}/>Administración</button><button className={section==='plans'?'active':''} onClick={()=>navigate('plans')}><SlidersHorizontal size={19}/>Gestionar planes</button></>}</nav><div className="sidebar-bottom"><div className="help-card"><span><Sparkles size={16}/>Un espacio para crecer</span><p>Consulta la capacidad y las funciones de tu plan.</p><button onClick={()=>navigate('plan')}>Ver mi plan<ArrowUpRight size={15}/></button></div><div className="profile"><span className="profile-avatar">{demo?'AC':session?.user.email?.slice(0,2).toUpperCase()}</span><div><strong>{demo?'Ana Castro':session?.user.email?.split('@')[0]}</strong><small>{ROLES[details.role]||'Mi cuenta'}</small></div><button aria-label={demo?'Salir de la demo':'Cerrar sesión'} onClick={logout}><LogOut size={17}/></button></div></div></aside>
 <div className="main-shell"><header className="topbar"><div className="breadcrumb"><button className="icon-button mobile-toggle" aria-label="Abrir menú" onClick={()=>setMobile(true)}><Menu size={22}/></button><Building2 size={16}/><span>Mi espacio</span><span className="slash">/</span><strong>{LABELS[section]}</strong></div><div className="topbar-right">{demo?<Badge tone="purple"><Eye size={13}/>Modo demostración</Badge>:<Badge tone="success"><ShieldCheck size={13}/>Sesión segura</Badge>}<button className="icon-button" aria-label="Ver ayuda" onClick={()=>setModal({type:'help'})}><CircleHelp size={19}/></button><span className="topbar-avatar">{demo?'AC':session?.user.email?.slice(0,2).toUpperCase()}</span></div></header>{demo&&<div className="demo-strip"><span>Datos de ejemplo. Los cambios duran hasta recargar y no envían mensajes.</span><button onClick={logout}>Ir al acceso real<ArrowRight size={14}/></button></div>}
 <main className="content">{error&&<div className="inline-error page-alert" role="alert"><AlertCircle size={18}/><span>{error}</span><button aria-label="Cerrar error" onClick={()=>setError('')}><X size={16}/></button></div>}{notice&&<div className="toast" role="status"><CheckCircle2 size={19}/>{notice}<button aria-label="Cerrar notificación" onClick={()=>setNotice('')}><X size={16}/></button></div>}
 <div className="page-heading"><div><div className="eyebrow">{section==='overview'?'TU OPERACIÓN, DE UN VISTAZO':section==='admin'||section==='plans'?'CONTROL DE LA PLATAFORMA':'TU ESPACIO DE TRABAJO'}</div><h1>{section==='overview'?`Todo listo, ${demo?'Ana':session?.user.email?.split('@')[0]||'bienvenido'}`:LABELS[section]}{section==='overview'&&<span className="welcome-dot">.</span>}</h1><p>{({overview:'Un nuevo día para conectar con tus clientes.',messages:'Cada conversación, en el mismo lugar.',whatsapp:'Conecta tu número y comienza a conversar.',team:'Las personas que hacen que todo funcione.',plan:'Capacidad y herramientas para tu negocio.',businesses:'Cada negocio con su propio espacio.',settings:'Haz que este espacio sea tuyo.',admin:'Gestiona los negocios y sus condiciones de acceso.',plans:'Define las funciones y los límites de cada plan.'})[section]}</p></div><div className="heading-actions"><button className="button secondary" onClick={()=>setReload(x=>x+1)} disabled={loading||!dataReady}><RefreshCw size={16}/>Actualizar</button>{['overview','messages'].includes(section)&&wid&&<button className="button primary" onClick={openSend} disabled={!sending||!dataReady||!details.connection}><Plus size={17}/>Nuevo mensaje</button>}{section==='businesses'&&<button className="button primary" onClick={()=>setModal({type:'business'})}><Plus size={17}/>Nuevo negocio</button>}{section==='team'&&managing&&dataReady&&<button className="button primary" onClick={()=>setModal({type:'member'})}><Plus size={17}/>Agregar usuario</button>}{section==='plans'&&isAdmin&&<button className="button primary" onClick={()=>setModal({type:'plan'})}><Plus size={17}/>Nuevo plan</button>}</div></div>
 {loading&&!workspaces.length?<div className="card"><Empty icon={RefreshCw} title="Cargando tus espacios…">Esto tomará un momento.</Empty></div>:!workspaces.length?<div className="card"><Empty icon={Building2} title="Dale un espacio a tu negocio" action={<button className="button primary" onClick={()=>setModal({type:'business'})}><Plus size={17}/>Crear mi primer negocio</button>}>Crea tu negocio para configurar el equipo y conectar WhatsApp.</Empty></div>:!dataReady?<div className="card"><Empty icon={RefreshCw} title="Cargando negocio…">Consultando los datos de este espacio.</Empty></div>:workspace?.status==='suspended'&&!isAdmin?<div className="card"><Empty icon={LockKeyhole} title="Este negocio está suspendido">Contacta al administrador de la plataforma para reactivar el acceso.</Empty></div>:<>
 {section==='overview'&&<><div className="metrics"><Metric icon={Send} label="Mensajes enviados" value={fmt(details.usage)} note={`de ${fmt(plan?.monthly_messages)} disponibles / mes`} color="purple"/><Metric icon={ArrowDownLeft} label="Mensajes recibidos" value={fmt(details.inbound)} note="En el mes actual · UTC" color="blue"/><Metric icon={Users} label="Miembros del equipo" value={details.members.length} note={`${plan?.max_members||0} lugares incluidos en tu plan`} color="orange"/><Metric icon={MessageCircle} label="Canal de WhatsApp" value={details.connection?'Conectado':'Por conectar'} note={details.connection?.display_phone||'Vincula tu número para comenzar'} color="green" text/></div><div className="overview-grid"><section className="card chart-card"><div className="card-head"><div><h2>Actividad de mensajes</h2><p>Últimos 7 días · muestra de hasta 200 mensajes</p></div><span className="period"><Clock3 size={14}/>Esta semana</span></div><div className="chart-legend"><span><i className="legend-out"/>Enviados</span><span><i className="legend-in"/>Recibidos</span></div><Chart messages={details.messages}/></section><section className="card channel-card"><div className="channel-top"><span className="whatsapp-icon"><MessageCircle size={26}/></span><Badge tone={details.connection?'success':'warning'}>{details.connection?'Conectado':'Pendiente'}</Badge></div><h2>Tu conexión con<br/>cada cliente.</h2><p>{details.connection?'WhatsApp está vinculado a tu negocio. Consulta tus mensajes y da el siguiente paso.':'Vincula WhatsApp Business para recibir mensajes y responder desde tu espacio.'}</p><div className="phone-detail"><span>{details.connection?'NÚMERO DEL NEGOCIO':'CANAL DISPONIBLE'}</span><strong>{details.connection?.display_phone||'WhatsApp Cloud API'}</strong></div><button className="button secondary" onClick={()=>navigate('whatsapp')}>{details.connection?'Administrar conexión':'Conectar WhatsApp'}<ArrowRight size={16}/></button></section></div><section className="card"><div className="card-head"><div><h2>Últimos mensajes</h2><p>El pulso de tus conversaciones.</p></div><button className="text-button" onClick={()=>navigate('messages')}>Ver todos<ArrowRight size={15}/></button></div><MessageTable onSelect={message=>setModal({type:'message',message})} messages={details.messages} compact/></section><div className="bottom-grid"><section className="card"><div className="card-head"><h2>Actividad del espacio</h2><Activity size={18} className="muted"/></div><ActivityList items={details.activity.slice(0,3)}/></section><section className="card plan-summary"><Badge tone="purple">PLAN {plan?.name?.toUpperCase()}</Badge><h2>Espacio para seguir creciendo</h2><p>{fmt(Math.max(0,(plan?.monthly_messages||0)-details.usage))} mensajes disponibles este mes.</p><div className="usage-row"><span>Uso mensual</span><strong>{Math.round(details.usage/Math.max(1,plan?.monthly_messages||1)*100)}%</strong></div><progress value={Math.min(details.usage,plan?.monthly_messages||1)} max={plan?.monthly_messages||1}/><button className="text-button" onClick={()=>navigate('plan')}>Explorar mi plan<ArrowRight size={15}/></button></section></div></>}
 {section==='messages'&&<section className="card"><div className="card-head filters"><div className="tabs">{[['all','Todos'],['inbound','Recibidos'],['outbound','Enviados']].map(([key,label])=><button key={key} className={filter===key?'selected':''} onClick={()=>setFilter(key)}>{label}</button>)}</div><label className="search"><Search size={17}/><input aria-label="Buscar mensajes" placeholder="Buscar número o mensaje…" value={search} onChange={e=>setSearch(e.target.value)}/></label></div><MessageTable onSelect={message=>setModal({type:'message',message})} messages={details.messages.filter(m=>(filter==='all'||m.direction===filter)&&`${m.phone} ${m.content}`.toLowerCase().includes(search.toLowerCase()))}/><div className="table-footer">Hasta los 200 mensajes más recientes. Actualiza para consultar nuevos eventos.</div></section>}
 {section==='social'&&<SocialChannels demo={demo} channels={details.metaChannels||[]} managing={managing} workspaceId={wid} api={api} onChange={patch=>demo?changeDemo(patch):setReload(x=>x+1)}/>} {section==='whatsapp'&&<div className="settings-grid"><section className="card padded"><div className="section-icon green"><MessageCircle size={26}/></div><h2>WhatsApp Business</h2><p className="muted">Una conexión independiente para {workspace.name}.</p>{details.connection?<><div className="connection-details"><Badge tone="success"><Check size={14}/>Credenciales verificadas</Badge><h3>{details.connection.verified_name||workspace.name}</h3><strong>{details.connection.display_phone}</strong><dl><dt>Phone Number ID</dt><dd>{details.connection.phone_number_id}</dd><dt>WhatsApp Business ID</dt><dd>{details.connection.waba_id}</dd><dt>Última conexión</dt><dd>{date(details.connection.connected_at)}</dd></dl></div>{managing&&<div className="button-row"><button className="button secondary" onClick={()=>setModal({type:'connection'})}>Actualizar credenciales</button><button className="button danger-button" onClick={()=>setModal({type:'disconnect'})}><Unplug size={15}/>Desconectar</button></div>}</>:<Empty icon={Link2} title="Conecta tu primer número" action={managing?<button className="button primary" disabled={!plan?.whatsapp} onClick={()=>setModal({type:'connection'})}>Conectar WhatsApp<ArrowRight size={16}/></button>:null}>Usa un número registrado en WhatsApp Cloud API. {plan?.whatsapp?'':'Tu plan no incluye WhatsApp.'}</Empty>}</section><div><section className="card padded"><h2>Antes de comenzar</h2><ol className="steps"><li><span>1</span><div><strong>Prepara tu cuenta de Meta</strong><p>Necesitas una cuenta de WhatsApp Business y un número habilitado en Cloud API.</p></div></li><li><span>2</span><div><strong>Vincula tus credenciales</strong><p>Ingresa los identificadores del número y del negocio, y un token de acceso válido.</p></div></li><li><span>3</span><div><strong>Activa los eventos</strong><p>El administrador configura el webhook y suscribe el campo messages en Meta.</p></div></li></ol></section><div className="info-note"><ShieldCheck size={20}/><p>Los tokens se cifran en el servidor. Solo propietarios y administradores pueden modificar la conexión.</p></div></div></div>}
 {section==='team'&&<section className="card"><div className="card-head"><div><h2>Personas de este negocio</h2><p>{details.members.length} de {plan?.max_members} usuarios disponibles</p></div><Badge>{ROLES[details.role]}</Badge></div><div className="table-scroll"><table><thead><tr><th>Usuario</th><th>Rol</th><th>Acceso</th><th>Acciones</th></tr></thead><tbody>{details.members.map(m=><tr key={m.user_id}><td><div className="contact"><span className="member-avatar">{m.email.slice(0,2).toUpperCase()}</span><strong>{m.email}</strong></div></td><td><Badge tone={m.role==='owner'?'purple':'neutral'}>{ROLES[m.role]}</Badge></td><td><span className="status-text"><i/>Activo</span></td><td>{managing&&m.role!=='owner'&&m.user_id!==session?.user.id&&<button className="text-button" onClick={()=>setModal({type:'member',member:m})}>Gestionar<ArrowRight size={14}/></button>}</td></tr>)}</tbody></table></div><div className="table-footer">Los nuevos integrantes deben registrarse antes de agregarlos con su correo.</div></section>}
 {section==='plan'&&<><div className="plan-banner"><div><Badge tone="purple">TU PLAN ACTUAL</Badge><h2>{plan?.name}</h2><p>{plan?.description}</p></div><div><Badge tone="success">Activación manual</Badge><p>Sin cobros automáticos</p></div></div><div className="plans-grid">{plans.map(p=><section className={`card pricing-card ${p.id===plan?.id?'current':''}`} key={p.id}><div className="pricing-top"><h2>{p.name}</h2>{p.id===plan?.id&&<Badge tone="purple">Actual</Badge>}</div><p>{p.description}</p><h3>{fmt(p.monthly_messages)}<small> mensajes / mes</small></h3><ul><li><Check size={17}/>{p.max_members} usuarios por negocio</li><li><Check size={17}/>Panel y actividad del negocio</li><li>{p.whatsapp?<Check size={17}/>:<X size={17}/>}WhatsApp {p.whatsapp?'incluido':'no incluido'}</li></ul><button className="button secondary" onClick={()=>setModal({type:'planInfo',plan:p})}>{p.id===plan?.id?'Consultar condiciones':'Cómo cambiar de plan'}<ArrowRight size={15}/></button></section>)}</div><div className="info-note"><CircleHelp size={20}/><p>Los límites se renuevan el primer día del mes en UTC. Los intentos reservados, incluidos los fallidos o sin confirmar, consumen el límite. Los cargos de Meta se gestionan por separado.</p></div></>}
 {section==='businesses'&&<div className="business-grid">{workspaces.map(w=><section className="card business-card" key={w.id}><div className="business-card-top"><span className="business-avatar">{w.name.slice(0,1)}</span><Badge tone={w.status==='active'?'success':'warning'}>{w.status==='active'?'Activo':'Suspendido'}</Badge></div><h2>{w.name}</h2><p>{w.industry||'Sin sector especificado'}</p><div className="business-meta"><span>Plan</span><strong>{plans.find(p=>p.id===w.plan_id)?.name}</strong></div><button className="button secondary" onClick={()=>{setWid(w.id);navigate('overview');}}>Abrir espacio<ArrowRight size={16}/></button></section>)}<button className="new-business" onClick={()=>setModal({type:'business'})}><span><Plus size={25}/></span><strong>Tu siguiente negocio</strong><p>Crea un espacio independiente</p></button></div>}
 {section==='settings'&&<div className="settings-grid"><section className="card padded"><h2>Información del negocio</h2><p className="muted">Así identificamos tu espacio de trabajo.</p><Form key={wid+workspace.name} busy={busy} disabled={!managing} onSubmit={v=>run(async()=>{if(demo)setDemoData(d=>({...d,workspaces:d.workspaces.map(w=>w.id===wid?{...w,name:v.name,industry:v.industry,contact_email:v.email}:w)}));else await call('update_workspace',{wid,business_name:v.name,business_industry:v.industry,business_email:v.email});},'Configuración guardada.')}><Field label="Nombre del negocio"><input name="name" required minLength={2} maxLength={80} defaultValue={workspace.name}/></Field><Field label="Sector"><input name="industry" maxLength={80} defaultValue={workspace.industry}/></Field><Field label="Correo de contacto"><input type="email" name="email" required maxLength={254} defaultValue={workspace.contact_email}/></Field></Form></section><section className="card padded"><h2>Actividad reciente</h2><ActivityList items={details.activity}/></section></div>}
 {section==='admin'&&isAdmin&&<section className="card"><div className="card-head"><div><h2>Negocios de la plataforma</h2><p>{workspaces.length} negocios registrados</p></div><label className="search"><Search size={17}/><input aria-label="Buscar negocio" value={search} onChange={e=>setSearch(e.target.value)} placeholder="Buscar negocio…"/></label></div><div className="table-scroll"><table><thead><tr><th>Negocio</th><th>Plan</th><th>Estado</th><th>Alta</th><th>Acciones</th></tr></thead><tbody>{workspaces.filter(w=>w.name.toLowerCase().includes(search.toLowerCase())).map(w=><tr key={w.id}><td><strong>{w.name}</strong><small className="block muted">{w.contact_email}</small></td><td>{plans.find(p=>p.id===w.plan_id)?.name}</td><td><Badge tone={w.status==='active'?'success':'warning'}>{w.status==='active'?'Activo':'Suspendido'}</Badge></td><td className="muted">{date(w.created_at)}</td><td><button className="text-button" onClick={()=>setModal({type:'admin',workspace:w})}>Administrar<ArrowRight size={15}/></button></td></tr>)}</tbody></table></div></section>}
 {section==='plans'&&isAdmin&&<div className="plans-grid">{plans.map(p=><section className="card pricing-card" key={p.id}><h2>{p.name}</h2><p>{p.description}</p><h3>{fmt(p.monthly_messages)}<small> mensajes / mes</small></h3><ul><li><Users size={17}/>{p.max_members} usuarios</li><li><MessageCircle size={17}/>WhatsApp {p.whatsapp?'habilitado':'deshabilitado'}</li></ul><button className="button secondary" onClick={()=>setModal({type:'plan',plan:p})}><Settings2 size={16}/>Editar plan</button></section>)}</div>}
 </>}<footer className="footer"><span>nexo<span>.</span> <small>Tu negocio, conectado.</small></span><small>{demo?'Entorno de demostración':'Espacios de trabajo independientes'}</small></footer></main></div>
 {modal&&<Modal title={({message:'Detalle del mensaje',business:'Crear un negocio',member:modal.member?'Gestionar acceso':'Agregar usuario',send:'Nuevo mensaje',connection:'Conectar WhatsApp',disconnect:'Desconectar WhatsApp',admin:'Administrar negocio',plan:modal.plan?'Editar plan':'Crear plan',planInfo:'Condiciones del plan',help:'Tu espacio, paso a paso'})[modal.type]} onClose={()=>{if(!busy)setModal(null);}}>{error&&<div className="inline-error" role="alert">{error}</div>}
 {modal.type==='message'&&<><Badge tone={modal.message.direction==='inbound'?'neutral':'purple'}>{STATUS[modal.message.status]}</Badge><h3 className="message-number">+{modal.message.phone}</h3><div className="message-body">{modal.message.content}</div><p className="muted small">{date(modal.message.created_at)} · {modal.message.kind}</p>{modal.message.error_code&&<p className="error-text">Código de error: {modal.message.error_code}</p>}</>}
 {modal.type==='business'&&<Form busy={busy} label="Crear negocio" onSubmit={v=>run(async()=>{let id;if(demo){id=crypto.randomUUID();setDemoData(d=>({...d,workspaces:[...d.workspaces,{id,name:v.name,industry:v.industry,contact_email:'ana@example.com',plan_id:d.plans[0].id,status:'active',created_at:new Date().toISOString()}],details:{...d.details,[id]:{...blank,role:'owner',members:[{user_id:'demo-user',email:'ana@example.com',role:'owner'}]}}}));}else id=await call('create_workspace',{business_name:v.name,business_industry:v.industry});setWid(id);setSection('overview');},'Tu negocio está listo.')}><p className="muted">Cada negocio tiene sus propios usuarios, mensajes y conexión.</p><Field label="Nombre del negocio"><input name="name" placeholder="Ej. Estudio Oliva" minLength={2} maxLength={80} required autoFocus/></Field><Field label="Sector"><input name="industry" placeholder="Ej. Servicios profesionales" maxLength={80}/></Field></Form>}
 {modal.type==='member'&&<Form busy={busy} label="Guardar acceso" onSubmit={v=>run(async()=>{if(demo){const members=details.members.filter(m=>m.email!==v.email);if(members.length>=plan.max_members)throw new Error('Alcanzaste el límite de usuarios del plan.');changeDemo({members:[...members,{user_id:modal.member?.user_id||crypto.randomUUID(),email:v.email,role:v.role}]});}else await call('manage_member',{wid,member_email:v.email,member_role:v.role,remove_member:false});},'Acceso actualizado.')}><p className="muted">Agrega un usuario que ya tenga una cuenta registrada. No se envía una invitación por correo.</p><Field label="Correo del usuario"><input name="email" type="email" maxLength={254} required defaultValue={modal.member?.email} readOnly={!!modal.member} placeholder="persona@negocio.com"/></Field><Field label="Rol"><select name="role" defaultValue={modal.member?.role||'agent'}>{details.role==='owner'&&<option value="admin">Administrador · configuración, equipo y mensajes</option>}<option value="agent">Agente · consultar y enviar mensajes</option><option value="viewer">Lector · solo consulta</option></select></Field>{modal.member&&<button className="button danger-button" type="button" onClick={()=>run(async()=>{if(demo)changeDemo({members:details.members.filter(m=>m.user_id!==modal.member.user_id)});else await call('manage_member',{wid,member_email:modal.member.email,member_role:modal.member.role,remove_member:true});},'Acceso eliminado.')}><X size={15}/>Eliminar acceso a este negocio</button>}</Form>}
 {modal.type==='send'&&<Form busy={busy} label={demo?'Simular envío':'Enviar mensaje'} onSubmit={v=>run(async()=>{if(demo){if(details.usage>=plan.monthly_messages)throw new Error('Alcanzaste el límite mensual.');changeDemo({messages:[{id:requestId,workspace_id:wid,phone:v.to,content:v.body,direction:'outbound',kind:messageKind,status:'read',created_at:new Date().toISOString()},...details.messages],usage:details.usage+1});setNotice('Envío simulado. No se contactó a ningún número.');}else{const parameters=v.parameters?v.parameters.split('\n').map(s=>s.trim()).filter(Boolean):[];const response=await api({action:'send',workspace_id:wid,request_id:requestId,to:v.to,kind:messageKind,body:v.body,language:v.language,parameters});if(response.message?.status==='failed')throw new Error('El envío anterior falló. Cierra el formulario para iniciar uno nuevo.');setNotice(response.warning||`Estado: ${STATUS[response.message?.status]||'registrado'}.`);}},null)}><Field label="Número del destinatario" hint="Código de país y número, sin +, espacios ni guiones."><input name="to" required pattern="[1-9][0-9]{7,14}" maxLength={15} placeholder="525512345678" inputMode="tel"/></Field><Field label="Tipo de mensaje"><select value={messageKind} onChange={e=>setMessageKind(e.target.value)}><option value="text">Texto · dentro de la ventana de 24 horas</option><option value="template">Plantilla aprobada por Meta</option></select></Field>{messageKind==='text'?<Field label="Mensaje" hint="El destinatario debe haberte escrito en las últimas 24 horas."><textarea name="body" rows={4} required maxLength={4096} placeholder="Escribe tu mensaje…"/></Field>:<><Field label="Nombre de la plantilla"><input name="body" required pattern="[a-z0-9_]+" maxLength={512} placeholder="hello_world"/></Field><Field label="Código de idioma"><input name="language" required defaultValue="es_MX" pattern="[a-z]{2,3}(_[A-Z]{2})?" maxLength={6}/></Field><Field label="Variables de texto del cuerpo (opcional)" hint="Una por línea y en orden. Plantillas de texto sin encabezado ni botones dinámicos."><textarea name="parameters" rows={3} maxLength={4000}/></Field></>}<div className="info-note compact"><ShieldCheck size={18}/><p>Envía solo a contactos que hayan aceptado recibir mensajes de tu negocio.</p></div></Form>}
 {modal.type==='connection'&&(demo?<><p className="muted">En la demo puedes simular una conexión. No ingreses credenciales reales.</p><button className="button primary" onClick={()=>run(async()=>{changeDemo({connection:{phone_number_id:'123456789',waba_id:'987654321',display_phone:'+52 55 0000 0000',verified_name:workspace.name,connected_at:new Date().toISOString()}});},'Conexión simulada correctamente.')}><Link2 size={16}/>Simular conexión</button></>:<Form busy={busy} label="Verificar y conectar" onSubmit={v=>run(async()=>{await api({action:'connect',workspace_id:wid,...v});},'Credenciales verificadas y guardadas.')}><Field label="Phone Number ID"><input name="phone_number_id" required pattern="[0-9]{5,30}" maxLength={30} inputMode="numeric" autoComplete="off"/></Field><Field label="WhatsApp Business Account ID"><input name="waba_id" required pattern="[0-9]{5,30}" maxLength={30} inputMode="numeric" autoComplete="off"/></Field><Field label="Token de acceso de Meta" hint="Se verifica y cifra en el servidor. No volverá a mostrarse."><input name="token" type="password" minLength={20} maxLength={4096} required autoComplete="new-password"/></Field></Form>)}
 {modal.type==='disconnect'&&<><p className="muted">Se eliminarán las credenciales de este negocio. El historial se conserva. Para enviar o recibir nuevamente tendrás que reconectar el número.</p><button className="button danger-button" disabled={busy} onClick={()=>run(async()=>{if(demo)changeDemo({connection:null});else await call('disconnect_whatsapp',{wid});},'WhatsApp desconectado.')}>Confirmar desconexión</button></>}
 {modal.type==='admin'&&<Form busy={busy} label="Guardar condiciones" onSubmit={v=>run(async()=>{const target=modal.workspace.id;if(demo)setDemoData(d=>({...d,workspaces:d.workspaces.map(w=>w.id===target?{...w,plan_id:v.plan,status:v.status}:w)}));else await call('admin_workspace',{wid:target,pid:v.plan,new_status:v.status});},'Cuenta actualizada.')}><p className="muted">{modal.workspace.name}</p><Field label="Plan asignado"><select name="plan" defaultValue={modal.workspace.plan_id}>{plans.map(p=><option key={p.id} value={p.id}>{p.name}</option>)}</select></Field><Field label="Estado de la cuenta"><select name="status" defaultValue={modal.workspace.status}><option value="active">Activa</option><option value="suspended">Suspendida</option></select></Field><div className="info-note compact"><AlertCircle size={18}/><p>Suspender bloquea el acceso operativo del cliente y los nuevos envíos.</p></div></Form>}
 {modal.type==='plan'&&<Form busy={busy} label="Guardar plan" onSubmit={v=>run(async()=>{const p={id:modal.plan?.id||crypto.randomUUID(),name:v.name,description:v.description,monthly_messages:Number(v.messages),max_members:Number(v.members),whatsapp:v.whatsapp==='on'};if(demo)setDemoData(d=>({...d,plans:modal.plan?d.plans.map(x=>x.id===p.id?p:x):[...d.plans,p]}));else await call('save_plan',{pid:modal.plan?.id||null,plan_name:p.name,message_limit:p.monthly_messages,member_limit:p.max_members,whatsapp_enabled:p.whatsapp,plan_description:p.description});},'Plan guardado.')}><Field label="Nombre"><input name="name" required minLength={2} maxLength={60} defaultValue={modal.plan?.name}/></Field><Field label="Descripción"><input name="description" maxLength={300} defaultValue={modal.plan?.description}/></Field><div className="field-row"><Field label="Mensajes al mes"><input name="messages" type="number" min={0} max={10000000} required defaultValue={modal.plan?.monthly_messages??1000}/></Field><Field label="Usuarios"><input name="members" type="number" min={1} max={10000} required defaultValue={modal.plan?.max_members||3}/></Field></div><label className="checkbox"><input name="whatsapp" type="checkbox" defaultChecked={modal.plan?.whatsapp??true}/>Incluir conexión de WhatsApp</label><p className="muted small">Los cambios se aplican a todos los negocios del plan. El registro utiliza el plan con menor límite de mensajes.</p></Form>}
 {modal.type==='planInfo'&&<><Badge tone="purple">{modal.plan.name}</Badge><p>Incluye {fmt(modal.plan.monthly_messages)} mensajes mensuales y {modal.plan.max_members} usuarios por negocio.</p><p className="muted">Para cambiar de plan, contacta al administrador indicando tu negocio y el plan solicitado. La activación es manual; no se realizan cobros automáticos.</p><button className="button secondary" onClick={()=>setModal(null)}>Entendido<Check size={16}/></button></>}
 {modal.type==='help'&&<><ol className="steps"><li><span>1</span><div><strong>Crea o selecciona un negocio</strong><p>Cada espacio mantiene separados los datos y el equipo.</p></div></li><li><span>2</span><div><strong>Agrega a tu equipo</strong><p>Los integrantes se registran y el propietario asigna permisos por correo.</p></div></li><li><span>3</span><div><strong>Conecta tu WhatsApp</strong><p>El administrador configura Meta y tú vinculas el número.</p></div></li><li><span>4</span><div><strong>Comienza a conversar</strong><p>Responde dentro de 24 horas o usa una plantilla aprobada. Actualiza el panel para consultar nuevos eventos.</p></div></li></ol><p className="muted small">El cobro automático y el asistente de IA son módulos adicionales; no están activos en esta versión base.</p></>}
 </Modal>}</div>;
}
function Metric({icon:Icon,label,value,note,color,text}){return <section className="metric"><div className="metric-top"><span>{label}</span><span className={`metric-icon ${color}`}><Icon size={18}/></span></div><strong className={text?'metric-text':''}>{value}</strong><p>{note}</p></section>;}
function ActivityList({items}){return items.length?<div className="activity-list">{items.map(a=><div key={a.id}><span className="activity-icon"><Check size={13}/></span><div><p>{a.description}</p><small>{date(a.created_at)}</small></div></div>)}</div>:<p className="muted padded">Aún no hay actividad registrada.</p>;}
function Chart({messages}){const days=Array.from({length:7},(_,i)=>{const day=new Date();day.setHours(0,0,0,0);day.setDate(day.getDate()-6+i);const next=new Date(day);next.setDate(next.getDate()+1);const list=messages.filter(m=>new Date(m.created_at)>=day&&new Date(m.created_at)<next);return{label:new Intl.DateTimeFormat('es-MX',{weekday:'short'}).format(day).replace('.',''),out:list.filter(m=>m.direction==='outbound').length,inbound:list.filter(m=>m.direction==='inbound').length};});const max=Math.max(4,...days.map(d=>Math.max(d.out,d.inbound)));return <div className="chart" role="img" aria-label={days.map(d=>`${d.label}: ${d.out} enviados, ${d.inbound} recibidos`).join('. ')}><div className="chart-scale">{[max,Math.round(max*.75),Math.round(max*.5),Math.round(max*.25),0].map((n,i)=><span key={i}>{n}</span>)}</div><div className="chart-plot"><div className="grid-lines">{[0,1,2,3,4].map(n=><i key={n}/>)}</div><div className="chart-columns">{days.map((d,i)=><div className="chart-day" key={i}><div className="bars" title={`${d.label}: ${d.out} enviados, ${d.inbound} recibidos`}><div className="bar bar-out" style={{height:`${d.out/max*100}%`}}/><div className="bar bar-in" style={{height:`${d.inbound/max*100}%`}}/></div><span>{d.label}</span></div>)}</div></div></div>;}

function SocialChannels({demo,channels,managing,workspaceId,api,onChange}) {
 const [channel,setChannel]=useState('instagram'),[form,setForm]=useState(false),[busy,setBusy]=useState(false),[error,setError]=useState('');
 const connected=channels.find(c=>c.channel===channel);
 async function submit(e){e.preventDefault();setBusy(true);setError('');const data=Object.fromEntries(new FormData(e.currentTarget));try{if(demo){onChange({metaChannels:[...channels.filter(c=>c.channel!==channel),{channel,page_id:data.page_id,account_id:data.account_id||'',display_name:channel==='instagram'?'Instagram demo':'Facebook demo',display_handle:data.handle||'',connected_at:new Date().toISOString()}]});}else{await api({action:'connect',workspace_id:workspaceId,channel,page_id:data.page_id,account_id:data.account_id,handle:data.handle,token:data.token});onChange({});}setForm(false);}catch(e){setError(e.message||'No se pudo conectar el canal.');}finally{setBusy(false);}}
 async function disconnect(){setBusy(true);setError('');try{if(demo)onChange({metaChannels:channels.filter(c=>c.channel!==channel)});else{await api({action:'disconnect',workspace_id:workspaceId,channel});onChange({});}}catch(e){setError(e.message||'No se pudo desconectar.');}finally{setBusy(false);}}
 return <div className="settings-grid"><section className="card padded"><div className="section-icon purple"><MessageCircle size={26}/></div><h2>Instagram y Facebook</h2><p className="muted">Configura los canales de mensajería de Meta por separado de WhatsApp.</p><div className="tabs channel-tabs"><button className={channel==='instagram'?'selected':''} onClick={()=>{setChannel('instagram');setError('');}}>Instagram</button><button className={channel==='facebook'?'selected':''} onClick={()=>{setChannel('facebook');setError('');}}>Facebook Messenger</button></div>{error&&<div className="inline-error" role="alert">{error}</div>}{connected?<div className="connection-details"><Badge tone="success"><Check size={14}/>Conectado</Badge><h3>{connected.display_name}</h3><strong>{connected.display_handle||connected.page_id}</strong><dl><dt>Page ID</dt><dd>{connected.page_id}</dd><dt>Cuenta vinculada</dt><dd>{connected.account_id||'Página de Facebook'}</dd><dt>Última conexión</dt><dd>{date(connected.connected_at)}</dd></dl>{managing&&<div className="button-row"><button className="button secondary" onClick={()=>setForm(true)}>Actualizar</button><button className="button danger-button" disabled={busy} onClick={disconnect}><Unplug size={15}/>Desconectar</button></div>}</div>:<Empty icon={Link2} title={`Conecta ${channel==='instagram'?'Instagram':'Facebook Messenger'}`} action={managing?<button className="button primary" onClick={()=>setForm(true)}>Configurar canal<ArrowRight size={16}/></button>:null}>Usa una página de Facebook administrada por tu aplicación de Meta. El token se cifra y no vuelve a mostrarse.</Empty>}</section><section className="card padded"><h2>Requisitos de Meta</h2><ol className="steps"><li><span>1</span><div><strong>Página y permisos</strong><p>Facebook Messenger usa una página; Instagram necesita una cuenta profesional vinculada a esa página.</p></div></li><li><span>2</span><div><strong>Token de página</strong><p>Genera un Page Access Token con los permisos de mensajería correspondientes en Meta.</p></div></li><li><span>3</span><div><strong>Webhook</strong><p>Suscribe los campos messages y messaging_postbacks en la misma URL de webhook de Meta.</p></div></li></ol><div className="info-note compact"><ShieldCheck size={18}/><p>Los mensajes entrantes se incorporarán al historial del negocio cuando el webhook de Meta esté suscrito.</p></div></section>{form&&<dialog open className="inline-dialog"><div className="modal-head"><h2>Conectar {channel==='instagram'?'Instagram':'Facebook Messenger'}</h2><button className="icon-button" onClick={()=>setForm(false)}><X size={20}/></button></div><form onSubmit={submit}><Field label="Page ID"><input name="page_id" required pattern="[0-9]{5,40}" maxLength={40}/></Field>{channel==='instagram'&&<Field label="Instagram account ID" hint="Si se deja vacío, se detecta desde la página."><input name="account_id" pattern="[0-9]{5,40}" maxLength={40}/></Field>}<Field label="Nombre de usuario o página"><input name="handle" maxLength={120} placeholder="@mi_negocio"/></Field><Field label="Page Access Token" hint="Se valida con Meta y se cifra en el servidor."><input name="token" type="password" minLength={20} maxLength={4096} required autoComplete="new-password"/></Field><div className="form-actions"><button className="button primary" disabled={busy} type="submit">{busy?'Verificando…':'Verificar y conectar'}<ArrowRight size={16}/></button></div></form></dialog>}</div>;
}






